window.LM.mountDashboard=function(root,requestedTab){'use strict';
const {icons,esc,fmt,money,modal,closeModal,toast,brand}=window.LM;
const KEY='lemniscate.workspace.v1';
const markets=[{id:'NVDA',name:'NVIDIA',spot:100,sigma:.5,glyph:'N',color:'#dfe8d1'},{id:'TSLA',name:'Tesla',spot:180,sigma:.6,glyph:'T',color:'#e7d8d2'},{id:'SPY',name:'S&P 500 ETF',spot:100,sigma:.3,glyph:'S',color:'#dce5ef'},{id:'QQQ',name:'Nasdaq 100 ETF',spot:100,sigma:.35,glyph:'Q',color:'#e5dfec'},{id:'HOOD',name:'Robinhood',spot:100,sigma:.5,glyph:'H',color:'#e8e1cc'}];
const tabs=[['overview','Overview'],['trade','Option chain'],['positions','Positions'],['shield','Shield'],['pool','Writer Pool'],['agents','Agent desk'],['activity','Activity']];
const defaults=()=>({version:1,balance:25000,positions:[],poolShares:0,poolQueues:[],watch:['NVDA','SPY'],policies:[],activity:[],settings:{name:'Account 01',slippage:.5,compact:false},history:[{t:Date.now(),equity:25000}]});
let state;try{const raw=JSON.parse(localStorage.getItem(KEY));state=raw?.version===1?{...defaults(),...raw,settings:{...defaults().settings,...raw.settings}}:defaults()}catch{state=defaults()}
let tab=requestedTab||new URLSearchParams(location.search).get('tab')||'overview';if(!tabs.some(x=>x[0]===tab)&&tab!=='settings')tab='overview';
let selected='NVDA',direction='call',speed='weekly',strikePct=0,quantity=10,search='',range='1W',poolMode='deposit',shieldPct=10,shieldQty=25;
const events=new AbortController();const listen=(type,fn)=>root.addEventListener(type,fn,{signal:events.signal});
const id=prefix=>prefix+'_'+(crypto.randomUUID?.()||Math.random().toString(36).slice(2)).slice(0,12);
let stored=null;try{stored=localStorage.getItem(KEY)}catch{}function persist(){try{const next=JSON.stringify(state);if(next!==stored){localStorage.setItem(KEY,next);stored=next}}catch{toast('Browser storage is full. Export your workspace to keep a copy.')}}
function optionValue(S,K,sigma,tau,isCall=true){if(!(S>0&&K>0&&sigma>0&&tau>0))return 0;const u=Math.sqrt(.25+2/(sigma*sigma*tau)),x=S/K;const C=S<=K?K/(2*u)*Math.pow(x,.5+u):(S-K)+K/(2*u)*Math.pow(x,.5-u);return Math.max(0,isCall?C:C-(S-K))}
function currentMarket(){return markets.find(x=>x.id===selected)||markets[0]}
const sessionFormatter=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});let sessionMinute=-1,sessionValue;function session(){const minute=Math.floor(Date.now()/60000);if(minute===sessionMinute)return sessionValue;sessionMinute=minute;sessionValue=calculateSession();return sessionValue}function calculateSession(){const n=new Date();const parts=sessionFormatter.formatToParts(n);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));const minutes=Number(p.hour)*60+Number(p.minute);if(p.weekday==='Sat'||p.weekday==='Sun'||minutes<240||minutes>=1200)return{name:'Closed session',spread:3,buys:false};if(minutes>=570&&minutes<960)return{name:'Regular hours',spread:1,buys:true};return{name:'Extended hours',spread:1.5,buys:true}}
function quote(opts={}){const m=opts.market||currentMarket(),kind=opts.direction||direction,sp=opts.speed||speed,rawUnits=Number(opts.quantity??quantity),q=Number.isFinite(rawUnits)&&rawUnits>0?rawUnits:0,K=opts.strike??m.spot*(1+strikePct/100),tau=(sp==='weekly'?7:1)/365;const mark=optionValue(m.spot,K,m.sigma,tau,kind==='call'),intrinsic=Math.max(0,kind==='call'?m.spot-K:K-m.spot);const unitSpread=Math.max(.01,mark*.02*session().spread);const fee=m.spot*q*.0003;return{market:m,direction:kind,speed:sp,units:rawUnits,strike:K,mark,tau,premium:mark*q,spread:unitSpread*q,fee,total:(mark+unitSpread)*q+fee,bid:Math.max(0,mark-unitSpread),daily:Math.max(0,mark-intrinsic)/(sp==='weekly'?7:1)*q,breakeven:kind==='call'?K+mark+unitSpread+fee/(q||1):K-mark-unitSpread-fee/(q||1)}}
function effective(p){const m=markets.find(x=>x.id===p.market),q=quote({market:m,direction:p.direction,speed:p.speed,strike:p.strike,quantity:1});const intrinsic=Math.max(0,p.direction==='call'?m.spot-p.strike:p.strike-m.spot);const decay=q.mark>0?Math.max(0,(q.mark-intrinsic)/q.mark)/(p.speed==='weekly'?7:1):0;return Math.max(0,p.units*Math.exp(-decay*Math.max(0,Date.now()-p.accruedAt)/86400000))}
function positionValue(p){const m=markets.find(x=>x.id===p.market);return quote({market:m,direction:p.direction,speed:p.speed,strike:p.strike,quantity:effective(p)}).premium}
function equity(){return state.balance+state.positions.reduce((a,p)=>a+positionValue(p),0)+state.poolShares*1.042+state.poolQueues.reduce((a,q)=>a+q.value,0)}
function dailyCost(){return state.positions.reduce((a,p)=>a+quote({market:markets.find(x=>x.id===p.market),direction:p.direction,speed:p.speed,strike:p.strike,quantity:effective(p)}).daily,0)}
function record(type,description,amount,detail={}){const r={id:id('lm'),type,description,amount,t:Date.now(),...detail};state.activity.unshift(r);state.history.push({t:Date.now(),equity:equity()});persist();return r}
function symbol(m){return `<span class="dash-symbol" style="background:${m.color}">${m.glyph}</span>`}
function button(label,action,style='',attrs=''){label=label.replace(/↗|↙|↓|↘|✧|\s\+$/g,()=>window.LM_ICON_SVGS.arrow);return `<button class="lm-button ${style}" data-action="${action}" ${attrs}>${label}</button>`}
function changeTab(t){tab=t;history.replaceState(null,'','/dashboard?tab='+t);render();scrollTo({top:0,behavior:'instant'})}
function line(label,value){return `<div class="dash-summary-line"><span>${label}</span><strong>${value}</strong></div>`}
function heading(title,sub,actions=''){return `<div class="dash-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="dash-actions">${actions}</div></div>`}
function chart(values,color='#b8873d',name='portfolio'){const v=values.length>1?values:[values[0]||0,values[0]||0];const min=Math.min(...v),max=Math.max(...v),spread=Math.max(1,max-min);const points=v.map((x,i)=>[i/(v.length-1)*700,150-(x-min)/spread*110]);const d=points.map(([x,y],i)=>(i?'L':'M')+x.toFixed(2)+','+y.toFixed(2)).join(' ');const fill=d+' L700,190 L0,190 Z';return `<svg class="dash-chart" viewBox="0 0 700 190" preserveAspectRatio="none" role="img" aria-label="${esc(name)} chart"><defs><linearGradient id="area-${name}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".18"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="M0 40H700M0 95H700M0 150H700" stroke="#28324c0c" stroke-dasharray="3 5"/><path d="${fill}" fill="url(#area-${name})"/><path class="chart-path" d="${d}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/><circle class="dash-equity-dot" cx="700" cy="${points.at(-1)[1]}" r="4"/></svg>`}
function spark(i){return `<svg class="spark" viewBox="0 0 80 30" aria-hidden="true"><path d="M1 ${22-i}L10 21L20 ${15+i}L31 18L40 9L52 ${12+i}L60 4L70 7L79 2" stroke="#b8873d" fill="none" stroke-width="1.3"/></svg>`}
function empty(title,copy,action='trade',label='Explore options'){return `<div class="glass dash-empty"><img src="/assets/lemniscate-mark-v2.webp" alt=""><h2>${title}</h2><p>${copy}</p>${button(label,'tab','gold',`data-tab="${action}"`)}</div>`}
function overview(){const values=state.history.slice(-({ '1D':8,'1W':24,'1M':60,'ALL':500}[range]||24)).map(x=>x.equity);values.push(equity());const open=state.positions.reduce((a,p)=>a+positionValue(p),0);return heading('A little more room to grow.','Your options, capital, and next move — in one clear view.',button('Add capital +','capital','gold')+button('View positions','tab','', 'data-tab="positions"'))+`<div class="dash-hero-grid"><section class="glass dash-portfolio"><div class="dash-portfolio-top"><div><span class="lm-eyebrow">Workspace value</span><h2>${money(equity())}</h2><span class="dash-change">${state.positions.length} open ${state.positions.length===1?'position':'positions'} <span>·</span> USDG</span></div><div class="dash-timeframes">${['1D','1W','1M','ALL'].map(x=>`<button class="${range===x?'active':''}" data-action="range" data-range="${x}">${x}</button>`).join('')}</div></div>${chart(values)}<div class="dash-chart-labels"><span>Capital and open option value</span><span>Now</span></div></section><section class="glass dash-orbits"><div class="dash-orbit gold"><span>Available capital</span><strong>${money(state.balance)}</strong><small>USDG</small></div><div class="dash-orbit blue"><span>Open option value</span><strong>${money(open)}</strong><small>${state.positions.length} positions</small></div><div class="dash-orbit blue"><span>Holding cost</span><strong>${money(dailyCost())}</strong><small>per day at current mark</small></div><div class="dash-orbit gold"><span>Writer Pool shares</span><strong>${fmt(state.poolShares,2)}</strong><small>at ${money(1.042)} NAV / share</small></div></section></div><div class="dash-under-grid"><section class="glass dash-panel"><div class="dash-panel-title"><h2>Find your next view</h2>${button('Open option chain ↗','tab','ghost small','data-tab="trade"')}</div>${markets.map((m,i)=>`<div class="dash-market-row">${symbol(m)}<div><h3>${m.id}</h3><p>${m.name}</p></div><strong>${money(m.spot)}</strong>${spark(i)}<button class="dash-star ${state.watch.includes(m.id)?'saved':''}" aria-label="${state.watch.includes(m.id)?'Remove':'Add'} ${m.id} ${state.watch.includes(m.id)?'from':'to'} watchlist" data-action="watch" data-market="${m.id}">${window.LM_ICON_SVGS.star}</button></div>`).join('')}</section><section class="glass dash-panel"><div class="dash-panel-title"><h2>More time. Clearer choices.</h2><span class="lm-sparkle">${window.LM_ICON_SVGS.star}</span></div><article class="dash-principle"><span class="lm-eyebrow">Protection, with a purpose</span><h3 style="margin-top:12px">A softer landing.</h3><p>Shield adds a Down option to a Stock Token holding. Choose a protection level and see its daily cost.</p>${button('Explore Shield '+icons.arrow,'tab','small','data-tab="shield"')}</article><article class="dash-principle"><h3>Your pace is yours.</h3><p>Daily and Weekly describe pricing speeds. Neither is an expiry date.</p><a class="lm-button small" href="/learn/daily-holding-cost">Read the mechanics ${icons.arrow}</a></article></section></div>`}
function ticket(){const q=quote(),err=validateQuote(q);return `<aside class="glass dash-ticket"><div class="dash-ticket-head"><h2>Your next view</h2><span>${q.market.id}</span></div><div class="lm-segmented" aria-label="Option direction"><button class="${direction==='call'?'selected':''}" data-action="direction" data-direction="call">Up call ${window.LM_ICON_SVGS.up}</button><button class="${direction==='put'?'selected':''}" data-action="direction" data-direction="put">Down put ${window.LM_ICON_SVGS.shield}</button></div><div class="dash-label"><span>Pricing speed</span><small>No expiry</small></div><div class="lm-segmented" aria-label="Option pricing speed"><button class="${speed==='daily'?'selected':''}" data-action="speed" data-speed="daily">Daily</button><button class="${speed==='weekly'?'selected':''}" data-action="speed" data-speed="weekly">Weekly</button></div><div class="dash-label">Strike</div><div class="dash-strikes">${[-10,-5,0,5,10].map(x=>`<button class="${strikePct===x?'active':''}" data-action="strike" data-strike="${x}">${money(q.market.spot*(1+x/100))}</button>`).join('')}</div><label class="dash-label" for="order-units">Option units<small>Available ${money(state.balance)}</small></label><input class="dash-field" id="order-units" aria-label="Option units" type="number" min="1" max="10000" step="1" value="${quantity}"><input class="dash-range" id="order-range" aria-label="Adjust option units" type="range" min="1" max="100" value="${Math.min(100,quantity)}"><div id="quote-summary">${quoteSummary(q,err)}</div></aside>`}
function quoteSummary(q,err){return `${line('Option premium',money(q.premium))}${line('Spread and notional fee',money(q.spread+q.fee))}${line('Daily holding cost',money(q.daily)+' / day')}${line('Pays off above / below',money(q.breakeven))}<div class="dash-ticket-total"><small>Purchase amount · maximum buyer loss</small><strong>${money(q.total)}</strong></div>${err?`<p class="dash-error" role="alert">${esc(err)}</p>`:''}${button('Review '+(direction==='call'?'Up call':'Down put')+' '+icons.arrow,'review','gold',err?'disabled':'')}<p class="dash-ticket-note">A continuing cost reduces effective units.<br>Loss is capped at your purchase amount.</p>`}
function trade(){const m=currentMarket(),q=quote();const filtered=markets.filter(x=>(x.id+' '+x.name).toLowerCase().includes(search.toLowerCase()));const vals=Array.from({length:25},(_,i)=>optionValue(m.spot*(.75+i/48),q.strike,m.sigma,q.tau,direction==='call'));return heading('A view, without the deadline.','Choose an underlying, direction, strike, and pace.',button('Understand costs '+icons.arrow,'cost-help','ghost'))+`<div class="dash-trade-layout"><section class="glass dash-chain"><div class="dash-search"><input id="market-search" aria-label="Search underlyings" placeholder="Search a Stock Token or ETF" value="${esc(search)}"><span>5 underlyings</span></div><div class="dash-instruments" id="market-results">${filtered.map(x=>marketButton(x)).join('')||'<p style="font-size:12px;color:#8994a3">No matching underlying.</p>'}</div><div class="dash-chain-head"><div><h2>${m.name}</h2><p>${m.id} · Underlying reference ${money(m.spot)}</p></div><span class="dash-session"><i></i>${session().name}</span></div>${chart(vals,'#b8873d','option-value')}<div class="dash-chart-caption"><span>Option value as the underlying changes</span><span>75% of reference → 125%</span></div><div class="dash-table-scroll"><table class="dash-chain-table"><thead><tr><th>Strike</th><th>Up call</th><th>Down put</th><th>${speed==='weekly'?'Weekly':'Daily'} cost / day</th><th></th></tr></thead><tbody>${[-10,-5,0,5,10].map(x=>{const K=m.spot*(1+x/100),call=quote({strike:K,direction:'call'}),put=quote({strike:K,direction:'put'});return `<tr class="${x===strikePct?'selected':''}"><td data-label="Strike">${money(K)} ${x===0?'<small style="color:#9b772f">ATM</small>':''}</td><td data-label="Up call">${money(call.mark)}</td><td data-label="Down put">${money(put.mark)}</td><td data-label="Cost / day">${money(call.daily/(quantity||1))}</td><td data-label=""><button data-action="strike" data-strike="${x}" aria-label="Select strike ${money(K)}">Select ${window.LM_ICON_SVGS.arrow}</button></td></tr>`}).join('')}</tbody></table></div></section>${ticket()}</div>`}
function marketButton(m){return `<button class="dash-instrument ${m.id===selected?'active':''}" data-action="market" data-market="${m.id}"><strong>${m.id}</strong><span>${m.name}</span><small>${money(m.spot)}</small></button>`}
function positions(){return heading('Your view, held in your wallet.','Effective units reduce with the continuing holding cost.',button('Export positions ↓','export-positions','ghost')+button('Open an option '+icons.arrow,'tab','gold','data-tab="trade"'))+(state.positions.length?`<div class="dash-info-strip"><div><strong>${state.positions.length} open ${state.positions.length===1?'position':'positions'}</strong> · ${money(state.positions.reduce((a,p)=>a+positionValue(p),0))} option value</div><span>${money(dailyCost())} / day holding cost</span></div><div class="dash-position-grid">${state.positions.map(p=>{const m=markets.find(x=>x.id===p.market),units=effective(p),q=quote({market:m,direction:p.direction,speed:p.speed,strike:p.strike,quantity:units}),pnl=q.premium-p.cost;return `<article class="glass dash-position"><div class="dash-position-head">${symbol(m)}<div><h2>${p.market} ${p.direction==='call'?'Up':'Down'}</h2><p>${p.speed==='weekly'?'Weekly':'Daily'} · Strike ${money(p.strike)} · No expiry</p></div></div><div class="dash-position-value">${money(q.premium)}</div><span class="dash-change" style="${pnl<0?'color:#af7a62;background:#f1e1d3':''}">${pnl>=0?'+':'−'}${money(Math.abs(pnl))} <span>since purchase</span></span>${line('Effective units',fmt(units,4))}${line('Daily holding cost',money(q.daily)+' /day')}${line('Purchase amount',money(p.cost))}${line('Bid per unit',money(q.bid))}<div class="dash-position-actions">${button('Position details','position-detail','','data-id="'+p.id+'"')}${button('Sell position ↗','sell','gold','data-id="'+p.id+'"')}</div></article>`}).join('')}</div>`:empty('Room for your first view.','Choose an everlasting Up or Down option.<br>Your position will appear here after the purchase.'))}
function shield(){const m=currentMarket(),q=quote({direction:'put',speed:'weekly',strike:m.spot*(1-shieldPct/100),quantity:shieldQty}),error=validateQuote(q);return heading('A little protection.<br>A little more peace of mind.','Protect a Stock Token holding with an everlasting Down option.')+`<div class="dash-shield-layout"><section class="glass dash-shield-visual"><span class="lm-eyebrow">Shield / ${m.id}</span><h2>Keep your holding.<br>Soften the downside.</h2><p>A Down option provides exposure below the strike. Choose your holding size and protection level, then review the cost before you add Shield.</p><svg class="dash-shield-graph" viewBox="0 0 600 240" role="img" aria-label="Holding with and without protection"><defs><linearGradient id="shieldfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b8873d" stop-opacity=".2"/><stop offset="1" stop-color="#b8873d" stop-opacity="0"/></linearGradient></defs><path d="M30 210H570M30 40V210" stroke="#28324c18" fill="none"/><path d="M30 190L570 40" stroke="#b6c9dd" stroke-width="2" fill="none"/><path d="M30 ${100+shieldPct*2}L${250+shieldPct*3} ${100+shieldPct*2}L570 40" stroke="#b8873d" stroke-width="2.5" fill="none"/><path d="M${250+shieldPct*3} 40V210" stroke="#b8873d50" stroke-dasharray="4 5"/><text x="${250+shieldPct*3}" y="230" text-anchor="middle" fill="#8c6b3d" font-size="11">Protection strike ${money(q.strike)}</text></svg><div class="dash-shield-legend"><span><i class="b"></i>Holding</span><span><i></i>Holding + intrinsic Down payoff</span></div><p style="font-size:10px;margin-top:20px">Payoff illustration before premium, funding, and spread. Effective protection units reduce over time.</p></section><aside class="glass dash-ticket"><div class="dash-ticket-head"><h2>Add your Shield</h2><span>Weekly Down</span></div><label class="dash-label" for="shield-market">Stock Token</label><select class="dash-field" id="shield-market">${markets.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${x.id} · ${x.name}</option>`).join('')}</select><label class="dash-label" for="shield-units">Holding units</label><input class="dash-field" id="shield-units" type="number" min="1" max="10000" value="${shieldQty}"><div class="dash-label">Protection level below reference</div><div class="dash-strikes">${[5,10,15].map(x=>`<button class="${x===shieldPct?'active':''}" data-action="shield-level" data-level="${x}">${x}% below</button>`).join('')}</div><div id="shield-summary">${shieldSummary(q,error)}</div></aside></div>`}
function shieldSummary(q,error){return `${line('Protection strike',money(q.strike))}${line('Daily holding cost',money(q.daily)+' /day')}<div class="dash-ticket-total"><small>Shield purchase amount</small><strong>${money(q.total)}</strong></div>${error?`<p class="dash-error">${esc(error)}</p>`:''}${button('Review protection '+icons.arrow,'review-shield','gold',error?'disabled':'')}<p class="dash-ticket-note">A Down option stays until you sell it.<br>Funding reduces its effective units.</p>`}
function pool(){return heading('Collateral with a clear role.','The counterparty pool, measured by NAV.',button('Pool mechanics '+icons.arrow,'pool-help','ghost'))+`<div class="dash-pool-grid"><section class="glass dash-pool-art"><div class="dash-pool-orb"><small>Writer Pool NAV</small><strong>$2.00M</strong><small>USDG collateral</small></div><div class="dash-pool-info"><span class="lm-eyebrow">The writer side</span><h2>Funding received.<br>Exposure managed.</h2><p>The pool sells options, receives funding and spread, and hedges its exposure. Shares accrue NAV and can lose value with market gaps or hedge losses.</p><div style="margin-top:20px">${line('Option value cap','35% of NAV')}<div class="dash-meter"><span style="width:25%"></span></div>${line('Per-name value cap','8% of NAV')}<div class="dash-meter"><span style="width:40%"></span></div></div></div></section><aside class="glass dash-ticket"><div class="dash-ticket-head"><h2>Your pool capital</h2><span>USDG</span></div><div class="lm-segmented"><button class="${poolMode==='deposit'?'selected':''}" data-action="pool-mode" data-mode="deposit">Deposit</button><button class="${poolMode==='withdraw'?'selected':''}" data-action="pool-mode" data-mode="withdraw">Withdraw</button></div>${line('Your pool shares',fmt(state.poolShares,4))}${line('Share NAV',money(1.042))}${line('Your pool value',money(state.poolShares*1.042))}<label class="dash-label" for="pool-amount">${poolMode==='deposit'?'Deposit amount in USDG':'Withdrawal amount in USDG'}</label><input id="pool-amount" class="dash-field" type="number" min="1" step=".01" placeholder="0.00"><p class="dash-ticket-note">${poolMode==='deposit'?'Deposits mint at NAV plus 10 basis points.':'Withdrawals enter a 72-hour queue and settle at NAV.'}</p>${button(poolMode==='deposit'?'Review deposit '+icons.arrow:'Review withdrawal '+icons.arrow,'pool-review','gold')}${state.poolQueues.length?`<p class="dash-transaction-note">${state.poolQueues.length} queued withdrawal${state.poolQueues.length===1?'':'s'} · ${money(state.poolQueues.reduce((a,q)=>a+q.value,0))}<br>Earliest release ${new Date(state.poolQueues[0].readyAt).toLocaleDateString('en-GB')}</p>`:''}</aside></div><div class="dash-vault-grid"><article class="glass dash-vault"><span class="lm-eyebrow">Phase 2 / Covered Up</span><h3>Write the upside you hold.</h3><p>Stock Tokens collateralize covered Up options, with one raw token unit per call unit. Deposits and withdrawals use seven-day epochs.</p>${button('Explore covered writing '+icons.arrow,'vault-up','small')}</article><article class="glass dash-vault"><span class="lm-eyebrow">Phase 2 / Cash Down</span><h3>Back the downside with USDG.</h3><p>USDG collateral equals strike multiplied by option units. A vault assumes a slice of the pool’s short exposure and receives its funding share.</p>${button('Explore cash-backed writing '+icons.arrow,'vault-down','small')}</article></div>`}
function agents(){return heading('Permission, with a boundary.','Budgets, expiry, and allowed names belong beside every agent.',button('Export policies ↓','export-policies','ghost'))+`<section class="glass dash-agent-banner"><div><span class="lm-eyebrow">Your agent desk</span><h2 style="margin-top:16px">Let a policy<br>hold the boundaries.</h2><p>Choose the allowed Stock Tokens, a spending budget, and an expiry. Review or revoke a policy whenever you need to.</p></div>${button('Create a policy +','create-policy','gold')}</section>`+(state.policies.length?`<div class="dash-policy-grid">${state.policies.map(p=>`<article class="glass dash-policy"><span class="dash-policy-status ${p.revoked?'revoked':''}">${p.revoked?'Revoked':p.expiry<Date.now()?'Expired':'Active'}</span><h3>${esc(p.name)}</h3>${line('Policy budget',money(p.budget))}${line('Access',p.access==='read'?'Read only':'Quote & execute')}${line('Expires',new Date(p.expiry).toLocaleDateString('en-GB'))}<div class="dash-policy-names">${p.names.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="dash-policy-actions">${button('Copy ID','copy-policy','small',`data-id="${p.id}"`)}${button('Download','download-policy','small',`data-id="${p.id}"`)}${!p.revoked?button('Revoke','revoke-policy','ghost small',`data-id="${p.id}"`):''}</div></article>`).join('')}</div>`:empty('Your boundaries start here.','Create a policy with a budget, allowed names, and an expiry.','agents','Create a policy'))}
function activity(){return heading('Every move, in one place.','Your purchases, exits, capital, and policy receipts.',button('Export activity ↓','export-activity','ghost'))+(state.activity.length?`<section class="glass dash-activity">${state.activity.map(r=>`<div class="dash-activity-row"><span class="action-icon">${window.LM_ICON_SVGS[r.type==='sell'?'wallet':r.type==='buy'||r.type==='shield'?'up':'activity']}</span><div><strong>${esc(r.description)}</strong><small>${new Date(r.t).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div><span>${esc(r.market||'Workspace')}</span><span style="text-align:right">${r.amount?money(Math.abs(r.amount)):r.type==='policy'?'Policy saved':'Recorded'}</span><button class="receipt" data-action="receipt" data-id="${r.id}">View receipt ${window.LM_ICON_SVGS.arrow}</button></div>`).join('')}</section>`:empty('A fresh page for your next move.','Activity appears here as you use the workspace.'))}
function settings(){return heading('Make the workspace yours.','Choose your account label, review preferences, and keep a copy of your records.')+`<div class="dash-settings"><section class="glass"><h2>Account preferences</h2><label class="dash-label" for="account-name">Account label</label><input class="dash-field" id="account-name" maxlength="35" value="${esc(state.settings.name)}"><label class="dash-label" for="slippage">Slippage preference</label><select class="dash-field" id="slippage">${[.1,.5,1,2].map(x=>`<option value="${x}" ${Number(state.settings.slippage)===x?'selected':''}>${x}%</option>`).join('')}</select><div style="margin-top:25px">${button('Save preferences '+icons.arrow,'save-settings','gold')}</div></section><section class="glass"><h2>Your records</h2><p style="font-size:12px;color:#8691a1;line-height:1.9">Export your complete workspace, including positions, capital activity, and agent policies. A fresh workspace clears the current browser’s records.</p><div class="dash-actions" style="margin-top:28px">${button('Export workspace ↓','export-workspace','')}${button('Fresh workspace','reset','ghost')}</div><div style="margin-top:30px">${line('Settlement unit','USDG')}${line('Pricing speeds','Daily · Weekly')}${line('Option expiry','None')}</div></section></div>`}
const mobileIcons={overview:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',trade:'M4 17l5-5 4 3 7-10 M15 5h5v5',positions:'M4 7h16v13H4z M8 7V4h8v3 M4 12h16',shield:'M12 3l8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6z M8 12l3 3 5-6',more:'M5 6h14 M5 12h14 M5 18h14',pool:'M4 10l8-6 8 6 M3 20h18 M5 10v10 M12 10v10 M19 10v10',agents:'M7 8h10v10H7z M12 3v5 M3 12h4 M17 12h4 M9 12h.01 M15 12h.01',activity:'M4 12h4l3-8 3 16 3-8h3',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6'};
function mobileIcon(key){return window.LM_ICON_SVGS[{overview:'home',trade:'chart',more:'menu'}[key]||key]||window.LM_ICON_SVGS.star}
function mobileNav(){return `<nav class="dash-mobile-nav" aria-label="Mobile workspace navigation">${[['overview','Home'],['trade','Trade'],['positions','Positions'],['shield','Shield'],['more','More']].map(([key,label])=>`<button class="${tab===key||(key==='more'&&['pool','agents','activity','settings'].includes(tab))?'active':''}" data-action="${key==='more'?'mobile-menu':'tab'}" ${key!=='more'?`data-tab="${key}"`:''} aria-label="${label}">${mobileIcon(key)}<span>${label}</span></button>`).join('')}</nav>`}
function mobileMenu(){const d=modal('Your workspace',`<div class="dash-mobile-menu">${[['pool','Writer Pool','Collateral and withdrawals'],['agents','Agent desk','Budgets and permissions'],['activity','Activity','Every move and receipt'],['settings','Account settings','Your preferences and records']].map(([key,label,detail])=>`<button data-mobile-tab="${key}">${mobileIcon(key)}<span><strong>${label}</strong><small>${detail}</small></span><b>${window.LM_ICON_SVGS.arrow}</b></button>`).join('')}<button data-mobile-help>${mobileIcon('shield')}<span><strong>Workspace help</strong><small>Understand your next move</small></span><b>${window.LM_ICON_SVGS.arrow}</b></button><a href="/">Explore Lemniscate ${icons.arrow}</a></div>`);d.classList.add('dash-menu-sheet');d.addEventListener('click',e=>{const b=e.target.closest('[data-mobile-tab]');if(b){closeModal();changeTab(b.dataset.mobileTab)}if(e.target.closest('[data-mobile-help]')){closeModal();root.querySelector('[data-action="help"]').click()}})}
function render(){root.innerHTML=`<main class="lm-ui lm-dashboard"><div class="dash-wrap"><header class="dash-header">${brand()}<div class="dash-header-right"><span class="dash-session"><i></i>${session().name}</span><a class="lm-button ghost small" href="/">Explore Lemniscate ${icons.arrow}</a><button class="dash-account" data-action="tab" data-tab="settings" aria-label="Account settings"><span>01</span><span>${esc(state.settings.name)}</span><span class="dash-account-chevron">${window.LM_ICON_SVGS.arrow}</span></button></div></header><nav class="dash-tabs" aria-label="Workspace navigation">${tabs.map(([key,label])=>`<button class="${tab===key?'active':''}" data-action="tab" data-tab="${key}" aria-current="${tab===key?'page':'false'}">${label}</button>`).join('')}</nav><div class="dash-page-entrance">${({overview,trade,positions,shield,pool,agents,activity,settings}[tab]||overview)()}</div><footer class="dash-bottom-line"><span>LEMNISCATE · More time. A clearer view.<br>Options can lose their entire purchase amount.</span><span><a href="/learn/everlasting-options">Understand your option ↗</a> &nbsp;·&nbsp; <a href="/product-terms">Product mechanics ↗</a></span></footer></div>${mobileNav()}<button class="lm-icon-button dash-help-button" data-action="help" aria-label="Workspace help">${window.LM_ICON_SVGS.help}</button></main>`;persist()}
function validateQuote(q){if(!session().buys)return'New purchases pause while the underlying session is closed.';if(!Number.isFinite(q.units)||q.units<1||q.units>10000)return'Enter between 1 and 10,000 option units.';if(!Number.isFinite(q.total)||q.total<=0)return'Choose a valid option size.';const current=state.positions.filter(p=>p.market===q.market.id&&p.direction===q.direction&&p.speed===q.speed&&p.strike===q.strike).reduce((n,p)=>n+positionValue(p),0);if(q.total+current>25000)return'The per-account series limit is $25,000.';if(q.total>state.balance)return'Available capital is below this purchase amount.';return''}
function purchase(q,shield=false){const err=validateQuote(q);if(err){toast(err);return}state.balance-=q.total;state.positions.push({id:id('position'),market:q.market.id,direction:q.direction,speed:q.speed,strike:q.strike,units:q.units,cost:q.total,accruedAt:Date.now(),openedAt:Date.now(),shield});record(shield?'shield':'buy',`${shield?'Shield · ':''}${q.market.id} ${q.direction==='call'?'Up':'Down'} · ${q.speed==='weekly'?'Weekly':'Daily'}`,-q.total,{market:q.market.id,units:q.units,strike:q.strike,premium:q.premium,fees:q.spread+q.fee});closeModal();tab='positions';history.replaceState(null,'','/dashboard?tab=positions');render();scrollTo({top:0,behavior:'smooth'});toast(shield?'Your Shield is in place.':'Your option position is open.')}
function review(q,shield=false){const err=validateQuote(q);if(err){toast(err);return}const d=modal(shield?'Review your protection':'Review your option',`<span class="lm-eyebrow">${q.market.id} · ${q.direction==='call'?'Up call':'Down put'} · ${q.speed==='weekly'?'Weekly':'Daily'}</span><div class="dash-modal-row"><span>Option units</span><strong>${fmt(q.units,2)}</strong></div><div class="dash-modal-row"><span>Strike</span><strong>${money(q.strike)}</strong></div><div class="dash-modal-row"><span>Premium</span><strong>${money(q.premium)}</strong></div><div class="dash-modal-row"><span>Spread and fee</span><strong>${money(q.spread+q.fee)}</strong></div><div class="dash-modal-row"><span>Daily holding cost</span><strong>${money(q.daily)} / day</strong></div><div class="dash-modal-total"><small>Purchase amount · maximum buyer loss</small><strong>${money(q.total)}</strong></div><p>There is no expiry. The continuing holding cost reduces effective units. Your option can lose its entire purchase amount.</p>`,button('Go back','modal-cancel','ghost')+button(shield?'Add Shield':'Open position','confirm-buy','gold'));d.querySelector('[data-action="confirm-buy"]').addEventListener('click',()=>purchase(q,shield));d.querySelector('[data-action="modal-cancel"]').addEventListener('click',closeModal)}
function sell(p){const units=effective(p),m=markets.find(x=>x.id===p.market);const d=modal('Exit your position',`<span class="lm-eyebrow">${p.market} · ${p.direction==='call'?'Up call':'Down put'} · ${p.speed}</span><label class="dash-label" for="sell-units">Effective units to sell</label><input class="dash-field" id="sell-units" type="number" min=".0001" max="${units}" step=".0001" value="${units.toFixed(4)}"><div id="sell-summary"></div><p class="dash-transaction-note">The bid includes the exit spread. A sale reduces the remaining option units and returns the proceeds to available capital.</p>`,button('Keep holding','modal-cancel','ghost')+button('Confirm exit','confirm-sell','gold'));const update=()=>{const qty=Number(d.querySelector('#sell-units').value),q=quote({market:m,direction:p.direction,speed:p.speed,strike:p.strike,quantity:qty}),net=Math.max(0,q.bid*qty-q.fee);const invalid=!Number.isFinite(qty)||qty<=0||qty>units+.0001;d.querySelector('#sell-summary').innerHTML=`<div class="dash-modal-total"><small>Exit proceeds after spread and fee</small><strong>${money(net)}</strong></div>${invalid?'<p class="dash-error">Enter a valid amount within your remaining units.</p>':''}`;d.querySelector('[data-action="confirm-sell"]').disabled=invalid;return{qty,net,invalid}};d.querySelector('#sell-units').addEventListener('input',update);update();d.querySelector('[data-action="modal-cancel"]').addEventListener('click',closeModal);d.querySelector('[data-action="confirm-sell"]').addEventListener('click',()=>{const {qty,net,invalid}=update();if(invalid)return;const old=effective(p);state.balance+=net;p.units=Math.max(0,old-qty);p.cost*=p.units/(old||1);p.accruedAt=Date.now();state.positions=state.positions.filter(x=>x.units>.00011);record('sell',`${p.market} ${p.direction==='call'?'Up':'Down'} exit`,net,{market:p.market,units:qty});closeModal();render();toast('Position exit completed.')})}
function capital(){const d=modal('Add capital to your workspace',`<p>Choose the USDG amount for available capital.</p><label class="dash-label" for="capital-amount">Amount in USDG</label><input id="capital-amount" class="dash-field" type="number" min="1" max="1000000" value="1000"><p class="dash-error" id="capital-error" hidden>Enter an amount from $1 to $1,000,000.</p>`,button('Go back','modal-cancel','ghost')+button('Add capital','confirm-capital','gold'));d.querySelector('[data-action="modal-cancel"]').onclick=closeModal;d.querySelector('[data-action="confirm-capital"]').onclick=()=>{const n=Number(d.querySelector('#capital-amount').value);if(!Number.isFinite(n)||n<1||n>1e6){d.querySelector('#capital-error').hidden=false;return}state.balance+=n;record('capital','Capital added',n);closeModal();render();toast(money(n)+' added to available capital.')}}
function poolReview(){const n=Number(document.getElementById('pool-amount').value);if(!(Number.isFinite(n)&&n>=1)){toast('Enter a valid USDG amount of at least $1.');return}if(poolMode==='deposit'&&n>state.balance){toast('Available capital is below this deposit amount.');return}if(poolMode==='withdraw'&&n>state.poolShares*1.042){toast('The withdrawal exceeds your pool value.');return}const deposit=poolMode==='deposit',shares=deposit?n/(1.042*1.001):n/1.042;const d=modal(deposit?'Review pool deposit':'Review pool withdrawal',`<div class="dash-modal-total"><small>${deposit?'USDG deposit':'USDG withdrawal request'}</small><strong>${money(n)}</strong></div>${line(deposit?'Shares to mint':'Shares entering the queue',fmt(shares,4))}${line('Share NAV',money(1.042))}<p style="margin-top:20px">${deposit?'Deposits mint at NAV plus a 10 basis point entry cost. Pool NAV can fall with losses.':'Your shares enter the 72-hour queue. The final withdrawal amount follows NAV at the end of that queue.'}</p>`,button('Go back','modal-cancel','ghost')+button(deposit?'Deposit capital':'Queue withdrawal','confirm-pool','gold'));d.querySelector('[data-action="modal-cancel"]').onclick=closeModal;d.querySelector('[data-action="confirm-pool"]').onclick=()=>{if(deposit){state.balance-=n;state.poolShares+=shares;record('pool','Writer Pool deposit',-n,{shares})}else{state.poolShares-=shares;state.poolQueues.push({id:id('queue'),shares,value:n,readyAt:Date.now()+72*3600000});record('pool','Writer Pool withdrawal queued',n,{shares})}closeModal();render();toast(deposit?'Your pool shares are recorded.':'Your withdrawal is in the 72-hour queue.')}}
function createPolicy(){const d=modal('Create an agent policy',`<label class="dash-label" for="policy-name">Policy name</label><input class="dash-field" id="policy-name" maxlength="40" value="My options agent"><label class="dash-label" for="policy-budget">Spending budget in USDG</label><input class="dash-field" id="policy-budget" type="number" min="1" max="25000" value="500"><div class="dash-label">Allowed names</div><div class="dash-checks">${markets.map((m,i)=>`<label><input type="checkbox" name="policy-market" value="${m.id}" ${i<2?'checked':''}>${m.id}</label>`).join('')}</div><label class="dash-label" for="policy-access">Permission</label><select class="dash-field" id="policy-access"><option value="read">Read only</option><option value="execute">Quote and execute</option></select><label class="dash-label" for="policy-expiry">Expiry</label><select class="dash-field" id="policy-expiry"><option value="1">24 hours</option><option value="7" selected>7 days</option><option value="30">30 days</option></select><p id="policy-error" class="dash-error" hidden>Choose a name, a budget from $1 to $25,000, and at least one underlying.</p>`,button('Go back','modal-cancel','ghost')+button('Create policy','confirm-policy','gold'));d.classList.add('dash-policy-sheet');d.querySelector('[data-action="modal-cancel"]').onclick=closeModal;d.querySelector('[data-action="confirm-policy"]').onclick=()=>{const name=d.querySelector('#policy-name').value.trim(),budget=Number(d.querySelector('#policy-budget').value),names=[...d.querySelectorAll('[name="policy-market"]:checked')].map(x=>x.value);if(!name||!Number.isFinite(budget)||budget<1||budget>25000||!names.length){d.querySelector('#policy-error').hidden=false;return}const p={id:id('policy'),name,budget,names,access:d.querySelector('#policy-access').value,expiry:Date.now()+Number(d.querySelector('#policy-expiry').value)*86400000,revoked:false};state.policies.push(p);record('policy','Agent policy created · '+name,0,{policy:p.id});closeModal();render();toast('Your policy is active.')}}
function download(name,data,type='application/json'){const body=typeof data==='string'?data:JSON.stringify(data,null,2),url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your export is ready.')}
function csv(rows){return rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\n')}
listen('input',e=>{if(e.target.id==='order-units'||e.target.id==='order-range'){quantity=Number(e.target.value);if(e.target.id==='order-range')root.querySelector('#order-units').value=quantity;else root.querySelector('#order-range').value=Math.min(100,quantity);root.querySelector('#quote-summary').innerHTML=quoteSummary(quote(),validateQuote(quote()))}if(e.target.id==='market-search'){search=e.target.value;root.querySelector('#market-results').innerHTML=markets.filter(x=>(x.id+' '+x.name).toLowerCase().includes(search.toLowerCase())).map(marketButton).join('')||'<p style="font-size:12px;color:#8994a3">No matching underlying.</p>'}if(e.target.id==='shield-units'){shieldQty=Number(e.target.value);const m=currentMarket(),q=quote({direction:'put',speed:'weekly',strike:m.spot*(1-shieldPct/100),quantity:shieldQty});root.querySelector('#shield-summary').innerHTML=shieldSummary(q,validateQuote(q))}});
listen('change',e=>{if(e.target.id==='shield-market'){selected=e.target.value;render()}});
listen('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
if(a==='tab'){if(tab==='agents'&&b.dataset.tab==='agents'&&b.closest('.dash-empty'))createPolicy();else changeTab(b.dataset.tab)}
else if(a==='mobile-menu')mobileMenu();
else if(a==='range'){range=b.dataset.range;render()}
else if(a==='market'){selected=b.dataset.market;render()}
else if(a==='direction'){direction=b.dataset.direction;render()}
else if(a==='speed'){speed=b.dataset.speed;render()}
else if(a==='strike'){strikePct=Number(b.dataset.strike);render()}
else if(a==='watch'){state.watch=state.watch.includes(b.dataset.market)?state.watch.filter(x=>x!==b.dataset.market):[...state.watch,b.dataset.market];render();toast('Watchlist updated.')}
else if(a==='review')review(quote());
else if(a==='review-shield'){const m=currentMarket();review(quote({direction:'put',speed:'weekly',strike:m.spot*(1-shieldPct/100),quantity:shieldQty}),true)}
else if(a==='shield-level'){shieldPct=Number(b.dataset.level);render()}
else if(a==='sell'){const p=state.positions.find(x=>x.id===b.dataset.id);if(p)sell(p)}
else if(a==='position-detail'){const p=state.positions.find(x=>x.id===b.dataset.id);if(p)modal(p.market+' position details',`${line('Direction',p.direction==='call'?'Up call':'Down put')}${line('Pricing speed',p.speed)}${line('Strike',money(p.strike))}${line('Effective units',fmt(effective(p),6))}${line('Purchase amount',money(p.cost))}${line('Opened',new Date(p.openedAt).toLocaleString('en-GB'))}<p style="margin-top:23px">A series normalization factor reduces effective option units with continuing funding. The option has no scheduled expiry.</p>`)}
else if(a==='capital')capital();
else if(a==='pool-mode'){poolMode=b.dataset.mode;render()}
else if(a==='pool-review')poolReview();
else if(a==='create-policy')createPolicy();
else if(a==='copy-policy'){try{await navigator.clipboard.writeText(b.dataset.id);toast('Policy ID copied.')}catch{modal('Your policy ID',`<p style="overflow-wrap:anywhere">${esc(b.dataset.id)}</p>`)}}
else if(a==='download-policy')download('lemniscate-policy.json',state.policies.find(x=>x.id===b.dataset.id));
else if(a==='revoke-policy'){const p=state.policies.find(x=>x.id===b.dataset.id);if(p){const d=modal('Revoke this policy?',`<p>${esc(p.name)} will no longer have permission to act under this policy.</p>`,button('Keep policy','modal-cancel','ghost')+button('Revoke policy','confirm-revoke','gold'));d.querySelector('[data-action="modal-cancel"]').onclick=closeModal;d.querySelector('[data-action="confirm-revoke"]').onclick=()=>{p.revoked=true;record('policy','Agent policy revoked · '+p.name,0);closeModal();render();toast('Policy revoked.')}}}
else if(a==='receipt'){const r=state.activity.find(x=>x.id===b.dataset.id);if(r){const d=modal('Your activity receipt',`${line('Action',esc(r.description))}${line('Amount',money(Math.abs(r.amount||0)))}${line('Time',new Date(r.t).toLocaleString('en-GB'))}<p style="overflow-wrap:anywhere;margin-top:25px;font-size:11px">Receipt ${esc(r.id)}</p>`,button('Download receipt ↓','download-receipt','gold'));d.querySelector('[data-action="download-receipt"]').onclick=()=>download('lemniscate-receipt.json',r)}}
else if(a==='export-positions')download('lemniscate-positions.csv',csv([['Underlying','Direction','Speed','Strike','Effective units','Value USDG','Purchase USDG'],...state.positions.map(p=>[p.market,p.direction,p.speed,p.strike,effective(p),positionValue(p),p.cost])]),'text/csv');
else if(a==='export-activity')download('lemniscate-activity.csv',csv([['Time','Action','Amount USDG','Receipt'],...state.activity.map(r=>[new Date(r.t).toISOString(),r.description,r.amount,r.id])]),'text/csv');
else if(a==='export-policies')download('lemniscate-agent-policies.json',state.policies);
else if(a==='export-workspace')download('lemniscate-workspace.json',state);
else if(a==='save-settings'){state.settings.name=root.querySelector('#account-name').value.trim()||'Account 01';state.settings.slippage=Number(root.querySelector('#slippage').value);render();toast('Preferences saved.')}
else if(a==='reset'){const d=modal('Start a fresh workspace?',`<p>This clears this browser’s positions, activity, pool records, and policies. Export your workspace first if you want a copy.</p>`,button('Keep workspace','modal-cancel','ghost')+button('Start fresh','confirm-reset','gold'));d.querySelector('[data-action="modal-cancel"]').onclick=closeModal;d.querySelector('[data-action="confirm-reset"]').onclick=()=>{state=defaults();closeModal();tab='overview';render();toast('Your workspace is ready.')}}
else if(a==='help')modal('A clearer workspace',`<p>Use the option chain to choose an Up call or Down put. Review the purchase amount, continuing holding cost, and strike before opening a position.</p><p style="margin-top:15px">Positions shows your effective units and exits. Shield adds Down protection to a holding. Writer Pool tracks collateral and a withdrawal queue. Agent desk manages budget and permission policies.</p>`);
else if(a==='cost-help')modal('Know the cost',`<p>The model uses everlasting pricing. Daily has a one-day mean and Weekly a seven-day mean. Neither expires.</p><p style="margin-top:18px">The quote combines premium, a spread with a $0.01 minimum, and a 3 basis point underlying notional fee. The daily cost reduces effective option units.</p>`);
else if(a==='pool-help')modal('The writer side',`<p>The Writer Pool sells options, receives funding and spread, and hedges exposure. NAV accounts for collateral, hedge equity, option liabilities, and reserve share.</p><p style="margin-top:18px">Deposits mint at NAV plus 10 basis points. Withdrawals use a 72-hour queue and settle at end-of-queue NAV. Market gaps and hedging losses can reduce NAV.</p>`);
else if(a==='vault-up'||a==='vault-down')modal(a==='vault-up'?'Covered Up vault':'Cash Down vault',`<span class="lm-eyebrow">Phase 2</span><p style="margin-top:20px">${a==='vault-up'?'Stock Tokens collateralize short calls at one raw unit per call unit.':'USDG collateral equals strike multiplied by put units.'} The vault assumes a slice of pool exposure and receives its funding and spread share.</p><p style="margin-top:18px">Vault deposits and withdrawals use seven-day epochs. Collateral limits the vault’s loss, and the vault is never liquidated.</p>`);
});
// Queued exits preserve NAV accounting while their release is pending.
const ready=state.poolQueues.filter(x=>x.readyAt<=Date.now());if(ready.length){state.balance+=ready.reduce((a,q)=>a+q.shares*1.042,0);state.poolQueues=state.poolQueues.filter(x=>x.readyAt>Date.now());record('pool','Writer Pool withdrawal released',ready.reduce((a,q)=>a+q.shares*1.042,0))}
window.LemniscateMath={optionValue,quote};render();window.LM.finishLoading();
return {dispose:()=>events.abort()};};
